-- Built In rotation text: each key is the rotation ID plus .Name or .Description.
if GetLocale() ~= "deDE" then return end
local addon_name = ...
local host = RotationMasterBuiltIns
local L = LibStub("AceLocale-3.0"):GetLocale(host and host.localeName or addon_name:match("^(.-)_[^_]+$") or addon_name)

L["rm.era.mage.fire.Name"] = "Feuer"
L["rm.era.mage.fire.Description"] = "Feuer von Stufe 10 bis 60, gewählt, wenn Sie Punkte in Feuer und keine in Frost haben oder Feuer Ihr Haupttalentbaum ist. Pyroschlag (sonst Feuerball) eröffnet; Pyroschlag nach Geistesgegenwart; Versengen hält mit Verbessertem Versengen fünf Stapel Feuerverwundbarkeit auf Zielen, die lange genug leben; Feuerschlag und Versengen erledigen; Feuerball füllt. Drei oder mehr Gegner im Kampf: Druckwelle, Flammenstoß, Arkane Explosion, Kältekegel, Blizzard. Erinnerungen: Verbrennung bei fünf Stapeln von Versengen gegen Elitegegner und bei langen Kämpfen, Rüstung, Arkane Intelligenz, Manaedelsteine, Eisbarriere, Manaschild, Hervorrufung, Gegenzauber, Geringen Fluch aufheben, Eisblock, Geistesgegenwart. Standardmäßig deaktiviert: Feuerschlag einweben, sobald er bereit ist."
L["rm.era.mage.fire.warcrafttavern.Name"] = "Feuer (Warcraft Tavern)"
L["rm.era.mage.fire.warcrafttavern.Description"] = "Feuer nach Warcraft Tavern, eine Alternative zur empfohlenen integrierten Feuerrotation, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität. Verbrennung wird gegen Elitegegner und Bosse beim Pull eingesetzt, statt auf Stapel von Versengen zu warten; Pyroschlag eröffnet; Versengen hält mit Verbessertem Versengen fünf Stapel; Feuerball füllt; Feuerschlag nur in Bewegung. Gruppen: zuerst Flammenstoß, dann Arkane Explosion, Kältekegel und Druckwelle aus der Nähe, Blizzard aus der Distanz. Dieselben Erinnerungen wie die integrierte Feuerrotation."
L["rm.era.mage.frost.Name"] = "Frost"
L["rm.era.mage.frost.Description"] = "Frost von Stufe 1 bis 60, auch für Arkan-Builds, und der Magier-Standard vor den Talenten. Frostblitz (Feuerball vor Stufe 4); Frostnova, wenn ein Gegner Sie erreicht, außer bei Schlachtzugsbossen; Arkane Geschosse, sobald ein Gegner Sie erreicht, wenn Sie Verbesserte arkane Geschosse haben; Kältekegel, Arkane Explosion und Blizzard, wenn drei oder mehr Gegner im Kampf sind; Feuerschlag in Bewegung bei überschüssigem Mana; Feuerschlag und der Zauberstab erledigen beim Solospiel gewöhnliche Gegner; Zauberstab ohne Mana. Erinnerungen: Rüstung (Eisrüstung solo, Magische Rüstung in einer Gruppe, ersetzt nie eine von Ihnen gewählte), Arkane Intelligenz, Herbeizaubern und Nutzen von Manaedelsteinen, Eisbarriere, Manaschild, Hervorrufung, Gegenzauber, Geringen Fluch aufheben, Eisblock, Kälteeinbruch, Arkane Macht und Geistesgegenwart. Standardmäßig deaktiviert: Flammenstoß für Zertrümmern und Frostblitz Rang 1 zum Stapeln von Winterkälte. Blinzeln, Verwandlung, Kiten und Zielwahl bleiben Ihnen überlassen."
L["rm.era.mage.frost.icyveins.Name"] = "Frost, AoE-Grinding (Icy Veins)"
L["rm.era.mage.frost.icyveins.Description"] = "Leveln mit Blizzard nach dem AoE-Grinding-Leitfaden von Icy Veins, automatisch gewählt, wenn Sie solo mit Verbessertem Blizzard spielen. Ab zwei Gegnern im Kampf: Frostnova auf die Gruppe, Kältekegel, während Frostnova abklingt, Blizzard, sobald nichts neben Ihnen steht, Arkane Explosion, wenn doch; Frostblitz gegen ein einzelnes Ziel, Feuerschlag und der Zauberstab zum Erledigen. Manaschild und Eisbarriere kommen vor jedem Pull. Das Sammeln der Gruppe, Blinzeln und Kiten bleiben Ihnen überlassen."
L["rm.forever.mage.arcane.Name"] = "Arkan"
L["rm.forever.mage.arcane.Description"] = "Arkan, sobald Arkan Ihr Haupttalentbaum mit 11 Punkten ist und Sie Arkanschlag beherrschen. Zieht solo mit Frostblitz oder in einer Gruppe mit Arkanschlag; dann Arkane Geschosse bei Geschosssalve, Arkanschlag bei Freizaubern, Arkaner Zorn bei drei Stapeln Arkanschlag, Arkanschlag bis zu vier Stapeln gegen Elitegegner und zwei gegen andere Ziele, solange Sie es sich leisten können (Mana ist unter Forever verborgen), dann Frostfeuerblitz, Frostblitz oder Feuerball, um auf Geschosssalve zu hoffen, und ein Zauberstab, wenn Sie solo sind und sich keinen Zauber leisten können. Ohne Arkaner Zorn (das ältere Beta-Design) verbraucht Feuerschlag die Stapel. In Bewegung: Feuerschlag. Drei oder mehr Gegner kämpfen gegen Sie: Arkane Explosion. Erinnerungen: Geistesgegenwart und Arkane Macht gegen Elitegegner (Arkane Macht wartet nicht mehr auf die Hälfte Ihres Manas) sowie die Magier-Pflegeerinnerungen."
L["rm.forever.mage.fire.Name"] = "Feuer"
L["rm.forever.mage.fire.Description"] = "Feuer, sobald Feuer Ihr Haupttalentbaum mit 11 Punkten ist (die Stufe von Pyroschlag). Zieht mit Pyroschlag gegen Elitegegner, sonst mit Frostfeuerblitz oder Feuerball; dann Pyroschlag bei drei Stapeln Aufwärmen, Eislanze bei Eisige Finger oder auf ein eingefrorenes Ziel (Feuer/Frost-Hybride), Feuerschlag bei Abklingzeit-Ende, Versengen, um Ihre fünf Stapel Feuerverwundbarkeit auf Elitegegnern zu halten, Frostfeuerblitz (ab 40) oder Feuerball, Zauberstab, wenn Sie solo sind und sich keinen Zauber leisten können. In Bewegung: Feuerschlag oder Eislanze. Vier oder mehr Gegner kämpfen gegen Sie: Flammenstoß, Druckwelle, Arkane Explosion. Versengen baut die Stapel erst auf, wenn Sie Verbessertes Versengen haben; ein Versengen auf kurze Distanz ist deaktiviert, bis Sie es aktivieren. Erinnerungen: Verbrennung und Geistesgegenwart gegen Elitegegner sowie die Magier-Pflegeerinnerungen."
L["rm.forever.mage.fire.icyveins.Name"] = "Feuer-Leveling (Icy Veins)"
L["rm.forever.mage.fire.icyveins.Description"] = "Feuer-Leveling-Build nach Icy Veins ohne Verbessertes Versengen, eine Alternative zur empfohlenen integrierten Feuerrotation, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität. Zieht mit Pyroschlag, nutzt Feuerschlag, um Feuersog zu verbrauchen, Versengen, während der Gegner herankommt (die Gesundheit des Ziels ist unter Forever verborgen, daher bleibt das Erledigen niedriger Ziele Ihnen überlassen), dann Frostfeuerblitz (ab 40) oder Feuerball. Derselbe Flächenschaden, dieselbe Bewegung, derselbe Zauberstab und dieselben Erinnerungen wie die integrierte Feuerrotation, ohne Verbrennung und Geistesgegenwart."
L["rm.forever.mage.frost.Name"] = "Frost"
L["rm.forever.mage.frost.Description"] = "Frost von Stufe 1 bis 60 und der Forever-Magier-Standard vor Talentzaubern (Feuerball bis Frostblitz auf Stufe 4). Zieht mit Frostblitz; dann Eislanze bei Eisige Finger oder auf ein eingefrorenes Ziel (auch während Frostblitz noch gewirkt wird, um abzubrechen oder zu bündeln), Kältekegel bei fünf Stapeln Winterkälte, Arkane Geschosse bei Geschosssalve, Frostblitz und ein Zauberstab, wenn Sie solo sind und sich Frostblitz nicht leisten können. In Bewegung: Eislanze, sonst Feuerschlag. Drei oder mehr Gegner kämpfen gegen Sie: Kältekegel; fünf oder mehr: Blizzard oder Arkane Explosion, wenn ein Gegner Sie angreift. Flächenschaden mit Flammenstoß und Arkaner Explosion nach Warcraft Tavern ist enthalten, aber deaktiviert. Erinnerungen: Arkane Intelligenz, Rüstung (Eis- oder Frostrüstung solo, Magische Rüstung in einer Gruppe, ersetzt nie eine von Ihnen gewählte), Eisbarriere, Gegenzauber, Geringen Fluch aufheben, Frostnova, wenn ein Gegner Sie erreicht, Kälteeinbruch. Gesundheit und Mana sind für Addons unter Forever verborgen, daher entscheiden Sie selbst, ob Sie niedrige Ziele mit Feuerschlag erledigen, sowie über Hervorrufung und Eisblock; Blinzeln, Kiten, Verwandlung und Manaedelsteine bleiben Ihnen ebenfalls überlassen."
L["rm.mop.mage.arcane.Name"] = "Empfohlen"
L["rm.mop.mage.arcane.Description"] = "Empfohlen für Arkan von Stufe 10 bis 90 (gewählt in der Spezialisierung Arkan). Arkanschlag baut vier Arkane Aufladungen auf; mit vier wird ein Proc von Arkane Geschosse! mit Geschossen verbraucht, und ohne einen kommt Arkanbeschuss, sobald Ihr Mana unter 90 % fällt. Über 95 % Mana wirkt sie weiter Arkanschlag, so wie der Simulator spielt. Geschosse werden nie mit zwei Procs liegen gelassen, Beschuss wird gewirkt, bevor Zeitverschiebung zurückspringt, und gegen zwei oder mehr Gegner kommt Beschuss bei jeweils vier Aufladungen; Kältekegel und Arkane Explosion, wenn fünf nah sind. Hält Ihre Talent-Bombe aufrecht und nutzt Feuerschlag oder Eislanze in Bewegung ohne Eisschollen. Erinnerungen: Arkane Macht und Zeitverschiebung bei vier Aufladungen mit einem Proc, Frostrüstung (Glühende Rüstung vor Stufe 54), Arkane Brillanz, Gegenzauber, Manaedelstein, Spiegelbild, Eisbarriere, Eisschollen, Rune der Kraft oder Herbeirufung. Zeitkrümmung, Zauberraub und Geistesgegenwart sind deaktiviert; Rune der Kraft muss weiterhin von Hand platziert werden."
L["rm.mop.mage.arcane.icyveins.Name"] = "Beschuss bei vier Aufladungen (Icy Veins)"
L["rm.mop.mage.arcane.icyveins.Description"] = "Die Arkan-Regel der Leitfäden (Icy Veins, Wowhead, Method, wowtbc.gg), eine Alternative zur empfohlenen integrierten Arkan-Rotation: bei vier Arkanen Aufladungen Arkane Geschosse, wenn ein Proc aktiv ist, sonst Arkanbeschuss, unabhängig von Ihrem Mana; Geschosse nur bei vier Aufladungen. Alles andere (Zeitverschiebung, Bomben, Flächenschaden, Bewegung, Erinnerungen) entspricht der empfohlenen, außer dass Arkane Macht bei vier Aufladungen vorgeschlagen wird, ohne auf einen Proc zu warten. Standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene integrierte Arkan-Rotation, oder erhöhen Sie ihre Priorität."
L["rm.mop.mage.fire.Name"] = "Empfohlen"
L["rm.mop.mage.fire.Description"] = "Empfohlen für Feuer von Stufe 10 bis 90 (gewählt in der Spezialisierung Feuer). Eröffnet mit einem voll gewirkten Pyroschlag, dann verwandelt Infernoschlag (Feuerschlag vor Stufe 24) Aufwärmen in einen Proc von Pyroschlag!, der sofort gewirkt wird, außer Einäschern ist gleich wieder bereit; dann wartet sie auf das nächste Aufwärmen, während Sie Feuerball wirken. Einäschern zündet direkt nach einem Pyroschlag, solange Entzünden und der Brand von Pyroschlag auf dem Ziel sind; das Addon kann nicht sehen, wie stark Entzünden ist, beurteilen Sie ein schwaches also selbst. Hält Ihre Talent-Bombe aufrecht, verteilt mit Infernoschlag, wenn zwei oder mehr Gegner gegen Sie kämpfen, Kältekegel und Arkane Explosion für fünf in der Nähe, Versengen in Bewegung. Erinnerungen: Glühende Rüstung, Geistesgegenwart, Zeitverschiebung mit beiden Procs, Manaedelstein, Arkane Brillanz, Gegenzauber, Spiegelbild, Eisbarriere, Eisschollen, Herbeirufung oder Rune der Kraft. Drachenodem, Zeitkrümmung und Zauberraub sind deaktiviert."
L["rm.mop.mage.fire.icyveins.Name"] = "Pyroschlag! zurückhalten (Icy Veins)"
L["rm.mop.mage.fire.icyveins.Description"] = "Die Feuer-Spielweise von Icy Veins, Method und wowtbc.gg, eine Alternative zur empfohlenen integrierten Feuerrotation: Ein Proc von Pyroschlag! wird zurückgehalten, bis Aufwärmen hinzukommt, dann zusammen mit Ihrem Feuerball gewirkt und allein nur verbraucht, wenn er bald ausläuft. Alles andere entspricht der empfohlenen. Standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene integrierte Feuerrotation, oder erhöhen Sie ihre Priorität."
L["rm.mop.mage.frost.Name"] = "Empfohlen"
L["rm.mop.mage.frost.Description"] = "Frost von Stufe 10 bis 90 (gewählt in der Spezialisierung Frost). Eislanze bei zwei Eisigen Fingern, Frostfeuerblitz bei Hirnfrost, Ihre Talent-Bombe, Gefrorene Kugel, Eislanze bei einem Eisigen Finger, Frostblitz; ab Stufe 87 wird ein Proc für Zeitverschiebung zurückgehalten, wenn diese weniger als 10 Sekunden entfernt ist. Gegen zwei oder mehr Gegner: Gefrorene Kugel, Kältekegel und Arkane Explosion, wenn sie nah sind, Blizzard, wenn vier stillstehen. Eislanze und Feuerschlag in Bewegung ohne Eisschollen. Erinnerungen: Wasserelementar, Eiskälte auf alles außer einem Boss (platzieren Sie sie selbst), Eisige Adern abgestimmt auf Zeitverschiebung, Zeitverschiebung bei zwei Eisigen Fingern während Eisige Adern, Frostrüstung (Glühende Rüstung vor Stufe 54), Manaedelstein, Arkane Brillanz, Gegenzauber, Spiegelbild, Eisbarriere, Eisschollen, Herbeirufung oder Rune der Kraft. Kälteeinbruch, Geistesgegenwart, Zeitkrümmung und Zauberraub sind deaktiviert."
L["rm.mop.mage.unspecialized.Name"] = "Vor einer Spezialisierung"
L["rm.mop.mage.unspecialized.Description"] = "Für Stufe 1 bis 9 und jeden Magier, der noch keine Spezialisierung gewählt hat. Frostfeuerblitz, Feuerschlag, um ein Ziel zu erledigen oder in Bewegung, Eislanze in Bewegung, sobald erlernt, Arkane Explosion, wenn drei oder mehr Gegner in Nahkampfreichweite sind. Erinnerungen: Frostnova, wenn ein Gegner Sie erreicht, Gegenzauber sowie Glühende Rüstung und Arkane Brillanz, sobald Sie sie erreichen. Die Wahl einer Spezialisierung auf Stufe 10 wechselt zur integrierten Rotation dieser Spezialisierung."
L["rm.retail.mage.arcane.Name"] = "Blizzard-Kampfassistent"
L["rm.retail.mage.arcane.Description"] = "Empfohlen für Arkan. Hebt den Zauber hervor, den Blizzards Kampfassistent als Nächstes vorschlägt, den einzigen Rotationshinweis, den das Spiel ein Addon im Kampf in Midnight noch auslesen lässt; sie wartet, während Sie wirken oder kanalisieren. Daneben Erinnerungen an das, was der Kampfassistent Ihnen überlässt: Arkane Woge im Kampf, Arkane Intelligenz außerhalb des Kampfes, Gegenzauber bei einem unterbrechbaren Zauber, Prismatische Barriere, wann immer sie im Kampf bereit ist, und Ihre Volksfähigkeit im Kampf. Gegnerische Zauber sind im Kampf verborgen, daher leuchtet Gegenzauber nur dort auf, wo das Spiel sie anzeigt; die Gesundheit ist unter Retail verborgen, daher bleiben Eisblock und andere Notfalltasten Ihnen überlassen. Spiegelbild, Zeitverschiebung, Blinzeln und Schmuckstücke bleiben Ihnen überlassen."
L["rm.retail.mage.arcane.guide.Name"] = "Referenz (Icy Veins und SimulationCraft)"
L["rm.retail.mage.arcane.guide.Description"] = "Nur als Referenz, standardmäßig deaktiviert: die Priorität der Leitfäden für Arkan. Arkansalve und Freizaubern sind im Kampf in Midnight für Addons verborgen (nur Arkane Aufladungen bleiben sichtbar), daher kann sie dort nicht laufen; Mana ist unter Retail verborgen, daher bleibt die Hervorrufung bei wenig Mana Ihnen überlassen; lesen Sie sie, oder duplizieren Sie sie, um damit zu experimentieren. Zieht mit Arkanschlag. Sonnenzorn: Arkane Geschosse bei Freizaubern unter 12 Stapeln Arkansalve, Prismatischer Blitz außerhalb von Arkaner Seele, Arkanbeschuss bei vier Aufladungen mit 12 Stapeln Arkansalve und Freizaubern oder mit 25 Stapeln Arkansalve, oder während Arkaner Seele bei beliebiger Zahl von Aufladungen, Prismatischer Blitz, Arkane Kugel unter drei Aufladungen, Arkaner Puls gegen drei Gegner oder ohne Aufladungen, Arkanschlag. Zauberer (Splitterzauberkunst erlernt): Prismatischer Blitz, Kugel gegen Gruppen, Beschuss bei 20 Stapeln Arkansalve (gegen zwei oder mehr Gegner nur bei vier Aufladungen), Geschosse bei Freizaubern unter 15 Stapeln Arkansalve, Kugel und Puls unter drei Aufladungen (kein Puls während Arkaner Woge), Arkanschlag. Arkanbeschuss, wenn Arkanschlag nicht gewirkt werden kann. Erinnerungen: Arkane Woge, Berührung der Magi nach einem Beschuss oder Prismatischen Blitz während oder lange vor der Woge, Geistesgegenwart ohne Aufladungen nach einem Beschuss, dazu die Erinnerungen der integrierten Kampfassistent-Rotation."
L["rm.retail.mage.fire.Name"] = "Blizzard-Kampfassistent"
L["rm.retail.mage.fire.Description"] = "Empfohlen für Feuer. Hebt den Zauber hervor, den Blizzards Kampfassistent als Nächstes vorschlägt, den einzigen Rotationshinweis, den das Spiel ein Addon im Kampf in Midnight noch auslesen lässt; sie wartet, während Sie wirken oder kanalisieren. Daneben Erinnerungen an das, was der Kampfassistent Ihnen überlässt: Einäschern im Kampf, Arkane Intelligenz außerhalb des Kampfes, Gegenzauber bei einem unterbrechbaren Zauber, Lodernde Barriere, wann immer sie im Kampf bereit ist, und Ihre Volksfähigkeit im Kampf. Gegnerische Zauber sind im Kampf verborgen, daher leuchtet Gegenzauber nur dort auf, wo das Spiel sie anzeigt; die Gesundheit ist unter Retail verborgen, daher bleiben Eisblock und andere Notfalltasten Ihnen überlassen."
L["rm.retail.mage.fire.guide.Name"] = "Referenz (Icy Veins, Wowhead und SimulationCraft)"
L["rm.retail.mage.fire.guide.Description"] = "Nur als Referenz, standardmäßig deaktiviert: die Priorität der Leitfäden für Feuer. Kampfeshitze, Aufwärmen, Pyroklasmus und die Aufladungen von Feuerschlag sind im Kampf in Midnight verborgen, daher kann sie dort nicht laufen. Feuerschlag, während ein Zauber endet, um Aufwärmen in Kampfeshitze zu verwandeln; zieht mit Pyroschlag. Pyroschlag (Flammenstoß gegen vier oder mehr Gegner) bei Hyperthermie, Meteor, Pyroschlag bei Kampfeshitze, Feuerschlag bei Aufwärmen während Einäschern, Pyroschlag bei Pyroklasmus, Versengen bei Hitzeschimmer oder in Bewegung, Feuerschlag bei Aufwärmen, dann Frostfeuerblitz oder Feuerball. Erinnerungen: Einäschern zum Ende eines regulär gewirkten Zaubers, Lodernde Barriere und die Erinnerungen an Hilfsfähigkeiten. Das Warten auf Feuerteufel und das Timing von Meteor in Einäschern bleiben Ihnen überlassen."
L["rm.retail.mage.frost.Name"] = "Blizzard-Kampfassistent"
L["rm.retail.mage.frost.Description"] = "Empfohlen für Frost. Hebt den Zauber hervor, den Blizzards Kampfassistent als Nächstes vorschlägt, den einzigen Rotationshinweis, den das Spiel ein Addon im Kampf in Midnight noch auslesen lässt; sie wartet, während Sie wirken oder kanalisieren. Daneben Erinnerungen an das, was der Kampfassistent Ihnen überlässt: Wasserelementar beschwören, wenn Sie das Talent und keinen Elementar haben, Arkane Intelligenz außerhalb des Kampfes, Gegenzauber bei einem unterbrechbaren Zauber, Eisbarriere, wann immer sie im Kampf bereit ist, und Ihre Volksfähigkeit im Kampf. Gegnerische Zauber sind im Kampf verborgen, daher leuchtet Gegenzauber nur dort auf, wo das Spiel sie anzeigt; die Gesundheit ist unter Retail verborgen, daher bleiben Eisblock und andere Notfalltasten Ihnen überlassen."
L["rm.retail.mage.frost.guide.Name"] = "Referenz (Icy Veins und SimulationCraft)"
L["rm.retail.mage.frost.guide.Description"] = "Nur als Referenz, standardmäßig deaktiviert: die Priorität der Leitfäden für Frost je Heldentalentbaum. Procs, Stapel von Eingefroren und Abklingzeiten sind im Kampf in Midnight verborgen, daher kann sie dort nicht laufen. Zieht mit Frostfeuerblitz oder Frostblitz. Frostfeuer (Frostfeuerblitz erlernt): Gletscherstachel, sobald bereit, Kometenhagel gegen einen oder zwei Gegner, Hagel bei Hirnfrost ohne Thermale Leere, Eislanze bei zwei Stapeln Eisige Finger, Froststrahl, Gefrorene Kugel, Blizzard bei Gefrierendem Regen gegen drei Gegner, Eislanze bei Eisigen Fingern mit Thermaler Leere oder bei zwölf Stapeln Eingefroren, Hagel, Eisnova oder Kältekegel gegen fünf, dann Gletscherstachel oder Frostfeuerblitz. Zauberer: Kometenhagel, Hagel bei Hirnfrost, Eislanze bei zwei Stapeln Eisige Finger, Gefrorene Kugel, Gletscherstachel, sobald bereit, Blizzard bei Gefrierendem Regen, Eislanze bei Eisigen Fingern oder sechs Stapeln Eingefroren, Froststrahl, Hagel, Eisnova oder Kältekegel gegen vier, Blizzard gegen sieben, dann Gletscherstachel oder Frostblitz. Eislanze in Bewegung. Erinnerungen: Wasserelementar beschwören, Eisbarriere und die Erinnerungen an Hilfsfähigkeiten."
L["rm.retail.mage.initial.Name"] = "Blizzard-Kampfassistent"
L["rm.retail.mage.initial.Description"] = "Empfohlen, bevor Sie eine Spezialisierung wählen (solange das Spiel die Anfangsspezialisierung des Magiers meldet). Hebt den Zauber hervor, den Blizzards Kampfassistent als Nächstes vorschlägt, den einzigen Rotationshinweis, den das Spiel ein Addon im Kampf in Midnight noch auslesen lässt; sie wartet, während Sie wirken oder kanalisieren. Daneben die Erinnerungen, die jede integrierte Magier-Rotation teilt, jeweils sobald Sie den Zauber kennen. Wenn Sie auf Stufe 10 eine Spezialisierung wählen, übernehmen die integrierten Rotationen dieser Spezialisierung."
L["rm.sod.mage.arcane.Name"] = "Arkan (SoD)"
L["rm.sod.mage.arcane.Description"] = "Arkanschaden in der Saison der Entdeckungen, gewählt, wenn Arkan Ihr Haupttalentbaum ist und Arkanschlag graviert ist. Arkane Geschosse bei Geschosssalve; Arkanbeschuss bei vier Stapeln Arkanschlag; Qualfeuerblitz, wenn es sicher ist, nie bei vier oder mehr Stapeln von Qualfeuerblitz; Lebende Flamme bei Abklingzeit-Ende; Arkanschlag füllt. Arkanbeschuss und Feuerschlag in Bewegung; Lebende Flamme und Arkane Explosion gegen Gruppen. Erinnerungen: Arkane Macht gegen Elitegegner und bei langen Kämpfen, Geistesgegenwart mit Arkaner Macht oder in Bewegung, Eisige Adern, Kälteeinbruch und die übrigen Magier-Erinnerungen."
L["rm.sod.mage.fire.Name"] = "Feuer (SoD)"
L["rm.sod.mage.fire.Description"] = "Feuer in der Saison der Entdeckungen von Stufe 1 bis 60 und dort der Magier-Standard. Nutzt die Runen, die Sie graviert haben: Pyroschlag bei Kampfeshitze sofort; Lebende Bombe auf Zielen, die lange genug leben, aufrechterhalten; Versengen mit Verbessertem Versengen, solange Feuerverwundbarkeit unter zwei Stapeln liegt oder bald ausläuft; Lebende Flamme bei Abklingzeit-Ende; Qualfeuerblitz bei fünf Stapeln Feuerverwundbarkeit, nie bei vier oder mehr Stapeln von Qualfeuerblitz (der fünfte tötet Sie); Frostfeuerblitz, sonst Feuerball. Lebende Bombe, Lebende Flamme und Feuerschlag in Bewegung; Lebende Flamme, Lebende Bombe, Druckwelle, Kältekegel, Flammenstoß und Blizzard gegen Gruppen. Erinnerungen: Feuerschlag bei Überhitzen, Verbrennung, Eisige Adern und Kälteeinbruch, Glühende oder eine andere Rüstung, Arkane Intelligenz, Manaedelsteine, Eisbarriere, Manaschild, Hervorrufung, Gegenzauber, Entfernen von Flüchen, Eisblock. Das Verteilen von Lebende Bombe auf mehrere Ziele bleibt Ihnen überlassen."
L["rm.sod.mage.frost.Name"] = "Frost (SoD)"
L["rm.sod.mage.frost.Description"] = "Frost in der Saison der Entdeckungen ab Stufe 10, gewählt, wenn Frost Ihr Haupttalentbaum ist. Eisige Finger gehen bei drei oder mehr Ihrer Stapel von Vergletscherung in Eislanze, sonst in Tieffrieren; Qualfeuerblitz bei einem Proc von Hirnfrost und sonst, wenn es sicher ist, nie bei vier oder mehr Stapeln von Qualfeuerblitz; Lebende Bombe und Lebende Flamme, wenn graviert; Zauberfrostblitz, sonst Frostfeuerblitz, sonst Frostblitz. Eislanze, Gefrorene Kugel, Lebende Bombe und Feuerschlag in Bewegung; Gefrorene Kugel, Lebende Flamme, Lebende Bombe, Blizzard und Kältekegel gegen Gruppen. Erinnerungen: Gefrorene Kugel, Eisige Adern, Kälteeinbruch, Rüstung, Manaedelsteine und die übrigen Magier-Erinnerungen. Einen Zauber in die Warteschlange zu stellen, während ein Blitz einschlägt, bleibt Ihnen überlassen."
L["rm.sod.mage.frost.warcrafttavern.Name"] = "Frost, Feuerrunen (SoD, Warcraft Tavern)"
L["rm.sod.mage.frost.warcrafttavern.Description"] = "Der Frost-Build von Warcraft Tavern für Phase 4 mit Feuerrunen, eine Alternative zur empfohlenen integrierten Frostrotation der Saison der Entdeckungen, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität. Pyroschlag eröffnet; Pyroschlag bei Kampfeshitze; Lebende Bombe aufrechterhalten; Versengen mit Verbessertem Versengen bis fünf Stapel; Qualfeuerblitz nur bei einem Proc von Hirnfrost und nie bei vier oder mehr Stapeln von Qualfeuerblitz; Frostfeuerblitz füllt. Lebende Bombe und Feuerschlag in Bewegung; Lebende Bombe, Kältekegel und Blizzard gegen Gruppen. Erinnerungen: Feuerschlag bei Überhitzen, Gefrorene Kugel während Eisige Adern, Eisige Adern, Kälteeinbruch und die übrigen Magier-Erinnerungen."
L["rm.sod.mage.healer.Name"] = "Heiler (SoD)"
L["rm.sod.mage.healer.Description"] = "Magier-Heilung in der Saison der Entdeckungen, gewählt, wenn Regeneration oder Massenregeneration graviert ist. Mit einem freundlichen Ziel: Zeit zurückdrehen und Chronostatische Bewahrung unter halber Gesundheit, Regeneration, wenn Ihr Zeitenleuchtfeuer fehlt, Massenregeneration, Zeitanomalie. Mit einem feindlichen Ziel Schaden, der Ihre Leuchtfeuer heilt: Zauberfrostblitz für Frost-Heiler, sonst Arkane Geschosse bei Geschosssalve, Arkanbeschuss bei zwei Stapeln Arkanschlag, Qualfeuerblitz, wenn es sicher ist (nie bei vier oder mehr Stapeln von Qualfeuerblitz), und Arkanschlag. Erinnerungen: Arkane Macht, Geistesgegenwart, Gefrorene Kugel und die übrigen Magier-Erinnerungen. Standardmäßig deaktiviert: Arkane Explosion gegen Gruppen sowie Eislanze und Tieffrieren für Frost-Heiler. Solange Sie Massenregeneration kanalisieren, wird der nächste Zauber bereits angezeigt, sodass Sie sie sofort abbrechen können (ihre direkte Heilung ist gering). Wen Sie heilen, bleibt Ihnen überlassen."
L["rm.tbc.mage.arcane.Name"] = "Arkan"
L["rm.tbc.mage.arcane.Description"] = "Arkan, gewählt, wenn Arkan Ihr Haupttalentbaum ist. Vor Stufe 64: Arkane Geschosse, mit Frostblitz bei knappem Mana. Ab 64: Arkanschlag in der Burn-Phase (Arkane Macht, Kampfrausch oder über 35 % Mana), sonst drei Stapel Arkanschlag und Frostblitz, bis sie auszulaufen drohen. Arkane Explosion und Kältekegel für drei oder mehr Gegner. Zu den Erinnerungen gehören Arkane Macht, Geistesgegenwart, Manaedelstein und Hervorrufung."
L["rm.tbc.mage.fire.icyveins.Name"] = "Feuer (Icy Veins)"
L["rm.tbc.mage.fire.icyveins.Description"] = "Feuer nach Icy Veins, gewählt, wenn Feuer Ihr Haupttalentbaum ist. Pyroschlag eröffnet einen Pull, sobald erlernt, Verbessertes Versengen hält fünf Stapel Feuerverwundbarkeit, Feuerball füllt, Feuerschlag ist für die Bewegung; Druckwelle, Drachenodem und Flammenstoß für drei oder mehr Gegner. Erinnerungen: Glühende, Magische oder Eisrüstung, Einäschern unter 20 % Gesundheit des Ziels, Manaedelstein, Hervorrufung und die gemeinsamen Magier-Hilfsmittel."
L["rm.tbc.mage.fire.wowhead.Name"] = "Feuer (Wowhead)"
L["rm.tbc.mage.fire.wowhead.Description"] = "Feuer nach Wowhead und Simulation. Wie die integrierte Feuer-Rotation nach Icy Veins, webt aber Feuerschlag ein, sobald er bereit ist, während Sie stillstehen (mehr Schaden, mehr Manaverbrauch), und eröffnet mit Feuerball statt Pyroschlag. Eine Alternative zur empfohlenen integrierten Feuerrotation nach Icy Veins, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität."
L["rm.tbc.mage.frost.Name"] = "Frost"
L["rm.tbc.mage.frost.Description"] = "Frost von Stufe 1 bis 70 und der Magier-Standard vor den Talenten. Frostblitz (Feuerball vor Stufe 4), Frostnova, wenn Sie etwas trifft, Kältekegel mit Blizzard oder Arkaner Explosion, wenn drei oder mehr Gegner im Kampf sind, Eislanze auf eingefrorene Ziele und in Bewegung, Zauberstab ohne Mana. Erinnerungen: Rüstung, Arkane Intelligenz, Manaedelstein, Hervorrufung, Gegenzauber, Zauberraub, Eisbarriere, Eisige Adern, Kälteeinbruch und Wasserelementar. Blinzeln, Eisblock, Kiten und Zielwahl bleiben Ihnen überlassen."
